-- SoilSync test schema v1. Run in soilsync_remake_test, after 000_create_database.sql.
-- Generated by scripts/export_schema.py. Password columns hold Argon2 hashes.

CREATE TABLE fertilizer_types (
	id SERIAL NOT NULL,
	name VARCHAR(100) NOT NULL,
	description TEXT,
	est_days_to_finish INTEGER DEFAULT '14' NOT NULL,
	PRIMARY KEY (id),
	CHECK (est_days_to_finish > 0),
	UNIQUE (name)
);

CREATE TABLE plants (
	id SERIAL NOT NULL,
	name VARCHAR(100) NOT NULL,
	plant_type VARCHAR(80) NOT NULL,
	growth_stage VARCHAR(50) NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (name)
);

CREATE TABLE rewards (
	id SERIAL NOT NULL,
	slug VARCHAR(60) NOT NULL,
	title VARCHAR(100) NOT NULL,
	description TEXT NOT NULL,
	points_cost INTEGER NOT NULL,
	category VARCHAR(80) NOT NULL,
	kind VARCHAR(30) NOT NULL,
	is_active BOOLEAN DEFAULT 'true' NOT NULL,
	prototype_only BOOLEAN DEFAULT 'true' NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	CHECK (points_cost > 0),
	UNIQUE (slug)
);

CREATE TABLE users (
	id SERIAL NOT NULL,
	username VARCHAR(40) NOT NULL,
	email VARCHAR(254) NOT NULL,
	password VARCHAR(255) NOT NULL,
	location VARCHAR(80) NOT NULL,
	points_balance INTEGER DEFAULT '0' NOT NULL,
	streak_days INTEGER DEFAULT '0' NOT NULL,
	tier VARCHAR(60) DEFAULT 'Tier 1: Beginner' NOT NULL,
	terms_version VARCHAR(30) NOT NULL,
	consented_at TIMESTAMP WITH TIME ZONE NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT users_nonnegative_points CHECK (points_balance >= 0),
	CONSTRAINT users_nonnegative_streak CHECK (streak_days >= 0)
);

CREATE UNIQUE INDEX users_email_unique ON users (lower(email));
CREATE UNIQUE INDEX users_username_unique ON users (lower(username));
CREATE TABLE waste_types (
	id SERIAL NOT NULL,
	name VARCHAR(100) NOT NULL,
	category VARCHAR(80) NOT NULL,
	is_supported BOOLEAN DEFAULT 'true' NOT NULL,
	rejection_reason VARCHAR(150),
	guide_recommendation TEXT,
	PRIMARY KEY (id),
	UNIQUE (name)
);

CREATE TABLE auth_sessions (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	token_hash VARCHAR(64) NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	UNIQUE (token_hash)
);

CREATE INDEX ix_auth_sessions_user_id ON auth_sessions (user_id);
CREATE TABLE batches (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	fertilizer_type_id INTEGER NOT NULL,
	batch_number VARCHAR(80) NOT NULL,
	name VARCHAR(60) NOT NULL,
	client_request_id VARCHAR(36) NOT NULL,
	status VARCHAR(20) DEFAULT 'Active' NOT NULL,
	percentage_completed INTEGER DEFAULT '0' NOT NULL,
	started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	est_completion_date DATE,
	PRIMARY KEY (id),
	UNIQUE (user_id, client_request_id),
	CHECK (percentage_completed IN (0, 33, 67, 100)),
	CHECK (status IN ('Active', 'Fermenting', 'Completed')),
	CHECK ((status = 'Completed') = (percentage_completed = 100)),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(fertilizer_type_id) REFERENCES fertilizer_types (id)
);

CREATE INDEX ix_batches_user_id ON batches (user_id);
CREATE TABLE daily_checkins (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	checkin_date DATE NOT NULL,
	points_awarded INTEGER DEFAULT '10' NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (user_id, checkin_date),
	CHECK (points_awarded = 10),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_daily_checkins_user_id ON daily_checkins (user_id);
CREATE TABLE fertilizer_maintenance_guides (
	id SERIAL NOT NULL,
	fertilizer_type_id INTEGER NOT NULL,
	check_cadence VARCHAR(100) NOT NULL,
	optimal_temp VARCHAR(150) NOT NULL,
	moisture_range VARCHAR(150) NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (fertilizer_type_id),
	FOREIGN KEY(fertilizer_type_id) REFERENCES fertilizer_types (id) ON DELETE CASCADE
);

CREATE TABLE fertilizer_recipe_steps (
	id SERIAL NOT NULL,
	fertilizer_type_id INTEGER NOT NULL,
	step_number INTEGER NOT NULL,
	instruction TEXT NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (fertilizer_type_id, step_number),
	CHECK (step_number > 0),
	FOREIGN KEY(fertilizer_type_id) REFERENCES fertilizer_types (id) ON DELETE CASCADE
);

CREATE TABLE fertilizer_suitable_plants (
	id SERIAL NOT NULL,
	fertilizer_type_id INTEGER NOT NULL,
	plant_id INTEGER NOT NULL,
	is_recommended BOOLEAN DEFAULT 'true' NOT NULL,
	notes VARCHAR(250),
	PRIMARY KEY (id),
	UNIQUE (fertilizer_type_id, plant_id),
	FOREIGN KEY(fertilizer_type_id) REFERENCES fertilizer_types (id) ON DELETE CASCADE,
	FOREIGN KEY(plant_id) REFERENCES plants (id) ON DELETE CASCADE
);

CREATE TABLE points_ledger (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	event_key VARCHAR(120) NOT NULL,
	points INTEGER NOT NULL,
	reason VARCHAR(150) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	CHECK (points <> 0),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	UNIQUE (event_key)
);

CREATE INDEX ix_points_ledger_user_id ON points_ledger (user_id);
CREATE TABLE reward_claims (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	reward_id INTEGER NOT NULL,
	request_id VARCHAR(36) NOT NULL,
	claim_code VARCHAR(50) NOT NULL,
	points_spent INTEGER NOT NULL,
	is_redeemed BOOLEAN DEFAULT 'false' NOT NULL,
	claimed_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (user_id, reward_id),
	UNIQUE (user_id, request_id),
	CHECK (points_spent > 0),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(reward_id) REFERENCES rewards (id),
	UNIQUE (claim_code)
);

CREATE INDEX ix_reward_claims_user_id ON reward_claims (user_id);
CREATE TABLE scan_logs (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	waste_type_id INTEGER,
	points_earned INTEGER DEFAULT '50' NOT NULL,
	image_sha256 VARCHAR(64) NOT NULL,
	provider VARCHAR(30) NOT NULL,
	model_name VARCHAR(100) NOT NULL,
	result JSONB NOT NULL,
	scanned_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (user_id, image_sha256),
	CHECK (points_earned IN (0, 50)),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
	FOREIGN KEY(waste_type_id) REFERENCES waste_types (id)
);

CREATE INDEX ix_scan_logs_user_id ON scan_logs (user_id);
CREATE TABLE user_settings (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	checkin_reminder BOOLEAN DEFAULT 'true' NOT NULL,
	reward_received_notify BOOLEAN DEFAULT 'true' NOT NULL,
	service_notices_notify BOOLEAN DEFAULT 'true' NOT NULL,
	claim_reward_reminder BOOLEAN DEFAULT 'true' NOT NULL,
	quiet_hours_start VARCHAR(5) DEFAULT '22:00' NOT NULL,
	quiet_hours_end VARCHAR(5) DEFAULT '07:00' NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (user_id),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE waste_fertilizer_matches (
	id SERIAL NOT NULL,
	waste_type_id INTEGER NOT NULL,
	fertilizer_type_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (waste_type_id, fertilizer_type_id),
	FOREIGN KEY(waste_type_id) REFERENCES waste_types (id) ON DELETE CASCADE,
	FOREIGN KEY(fertilizer_type_id) REFERENCES fertilizer_types (id) ON DELETE CASCADE
);

CREATE TABLE weekly_checkin_quests (
	id SERIAL NOT NULL,
	batch_id INTEGER NOT NULL,
	week_number INTEGER NOT NULL,
	status VARCHAR(10) DEFAULT 'UPCOMING' NOT NULL,
	points_reward INTEGER DEFAULT '100' NOT NULL,
	completed_at TIMESTAMP WITH TIME ZONE,
	image_proof_url VARCHAR(500),
	storage_key VARCHAR(300),
	note VARCHAR(250) DEFAULT '' NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (batch_id, week_number),
	CHECK (week_number BETWEEN 1 AND 3),
	CHECK (status IN ('UPCOMING', 'CURRENT', 'DONE')),
	CHECK (points_reward = 100),
	CHECK (status <> 'DONE' OR (completed_at IS NOT NULL AND image_proof_url IS NOT NULL)),
	FOREIGN KEY(batch_id) REFERENCES batches (id) ON DELETE CASCADE
);

CREATE INDEX ix_weekly_checkin_quests_batch_id ON weekly_checkin_quests (batch_id);
